[CmdletBinding()]
param([Parameter(Position=0)][string]$InputPath,[switch]$Recursive,[ValidateRange(0,[long]::MaxValue)][long]$MinBitrate=0,[switch]$Json,[string]$Output,[switch]$Help)
. "$PSScriptRoot/lib/Common.ps1"
if($Help){'transcodeaudit BETA - triage technical characteristics for provenance review';'Usage: .\transcodeaudit.ps1 FILE|DIR [-Recursive] [-MinBitrate bps] [-Json] [-Output path]';exit 0};if(-not $InputPath){[Console]::Error.WriteLine('input required');exit 2};Assert-CDLDependencies
try{$files=@(Get-CDLAudioFiles $InputPath -Recursive:$Recursive)}catch{[Console]::Error.WriteLine($_.Exception.Message);exit 2};if(-not $files.Count){[Console]::Error.WriteLine('no supported audio files found');exit 2};Assert-CDLReportTarget -Output $Output -Sources $files
$rows=@();$find=@();foreach($f in $files){$codec=Get-CDLProbeValue $f codec_name;$fmt=Get-CDLProbeValue $f format_name format;$rate=Get-CDLProbeValue $f sample_rate;$ch=Get-CDLProbeValue $f channels;$br=Get-CDLProbeValue $f bit_rate;if(-not $br){$br=Get-CDLProbeValue $f bit_rate format};$dur=Get-CDLProbeValue $f duration format;$enc=Get-CDLTag $f encoder;$rows+=[pscustomobject][ordered]@{path=$f;codec=$codec;container=$fmt;sample_rate=Convert-CDLIntOrNull $rate;channels=Convert-CDLIntOrNull $ch;bit_rate=Convert-CDLLongOrNull $br;duration_seconds=Convert-CDLDoubleOrNull $dur;file_size=(Get-Item -LiteralPath $f).Length;encoder=$enc};if($MinBitrate -gt 0 -and $br -match '^\d+$' -and [long]$br -lt $MinBitrate){$find+=New-CDLFinding 'low_reported_bitrate' "reported bitrate $br is below configured floor $MinBitrate" $f};if($codec -eq 'flac' -and $fmt -match 'mov|mp4'){$find+=New-CDLFinding 'unusual_lossless_container' 'lossless codec in an uncommon delivery container; inspect provenance if unexpected' $f}}
$status=if($find.Count){'review'}else{'ok'};$report=[ordered]@{tool='transcodeaudit';version=$script:CDLVersion;generated_utc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');inputs=@($InputPath);dependencies=Get-CDLVersions;options=[ordered]@{recursive=[bool]$Recursive;min_bitrate=$MinBitrate};measurements=[ordered]@{files=$rows};findings=$find;status=$status;limitations='These observations cannot prove lossy-to-lossless transcode history.'};Write-CDLReport $report -Json:$Json -Output $Output -Text "transcodeaudit BETA: $($rows.Count) file(s), status=$status";if($find.Count){exit 1};exit 0
